242: function normalizeState(raw) {
243:   if (!raw || typeof raw !== 'object' || !Array.isArray(raw.buildings) || !Array.isArray(raw.tenants)) throw new Error('bad save');
244:   raw.version = 1;
245:   raw.settings = { ...blankSettings(), ...(raw.settings || {}) };
246:   raw.xp = Math.max(0, num(raw.xp));
247:   raw.ledger = Array.isArray(raw.ledger) ? raw.ledger : [];
248:   if (!raw.month || typeof raw.month.y !== 'number') raw.month = todayMonth();
249:   raw.buildings = raw.buildings.map((b) => ({
250:     id: b.id || uid('bld'), name: String(b.name || 'Building'), color: THEMES[b.color] ? b.color : 'coral',
251:     floors: clamp(Math.round(num(b.floors, 3)), 1, 8), unitsPerFloor: clamp(Math.round(num(b.unitsPerFloor, 2)), 1, 5),
252:     emoji: b.emoji || '🏠',
253:   }));
254:   raw.tenants = raw.tenants.map((t) => ({
255:     id: t.id || uid('ten'), name: String(t.name || 'Tenant'), emoji: t.emoji || '👤',
256:     buildingId: t.buildingId, unit: String(t.unit || ''), rent: roundMoney(num(t.rent)),
257:     paidThisMonth: roundMoney(num(t.paidThisMonth)), prevDue: roundMoney(num(t.prevDue)), due: roundMoney(num(t.due)),
258:     createdAt: t.createdAt || Date.now(),
259:   })).filter((t) => raw.buildings.some((b) => b.id === t.buildingId));
260:   raw.ledger = raw.ledger.map((e) => ({
261:     ...e, rent: num(e.rent), prevDue: num(e.prevDue), amount: num(e.amount), dueAfter: num(e.dueAfter),
262:   }));
263:   raw.updatedAt = raw.updatedAt || Date.now();
264:   return raw;
265: }
