300: const AudioKit = (() => {
301:   let ctx = null;
302:   function ensure() {
303:     if (!state.settings.sound) return null;
304:     const C = window.AudioContext || window.webkitAudioContext;
305:     if (!C) return null;
306:     if (!ctx) ctx = new C();
307:     if (ctx.state === 'suspended') ctx.resume().catch(() => {});
308:     return ctx;
309:   }
310:   function tone(freq, at, dur, type = 'sine', vol = 0.06, slideTo = null) {
311:     const c = ensure(); if (!c) return;
312:     const o = c.createOscillator(); const g = c.createGain();
313:     o.type = type; o.frequency.setValueAtTime(freq, c.currentTime + at);
314:     if (slideTo) o.frequency.exponentialRampToValueAtTime(slideTo, c.currentTime + at + dur);
315:     g.gain.setValueAtTime(0.0001, c.currentTime + at);
316:     g.gain.exponentialRampToValueAtTime(vol, c.currentTime + at + 0.012);
317:     g.gain.exponentialRampToValueAtTime(0.0001, c.currentTime + at + dur);
318:     o.connect(g).connect(c.destination);
319:     o.start(c.currentTime + at); o.stop(c.currentTime + at + dur + 0.02);
320:   }
321:   function noise(dur = 0.16, vol = 0.04, freq = 2200) {
322:     const c = ensure(); if (!c) return;
323:     const buffer = c.createBuffer(1, Math.floor(c.sampleRate * dur), c.sampleRate);
324:     const data = buffer.getChannelData(0);
325:     for (let i = 0; i < data.length; i++) data[i] = (Math.random() * 2 - 1) * (1 - i / data.length);
326:     const src = c.createBufferSource(); src.buffer = buffer;
327:     const filter = c.createBiquadFilter(); filter.type = 'bandpass'; filter.frequency.value = freq; filter.Q.value = .8;
328:     const g = c.createGain(); g.gain.value = vol;
329:     src.connect(filter).connect(g).connect(c.destination); src.start();
330:   }
331:   return {
332:     click() { tone(420, 0, .04, 'triangle', .018); },
333:     coin() { tone(1180, 0, .07, 'sine', .05); tone(1560, .055, .14, 'sine', .042); },
334:     register() { noise(.18, .05, 2600); [880, 1320, 1760, 2093].forEach((f, i) => tone(f, i * .05, .2, 'triangle', .045)); },
335:     level() { [523, 659, 784, 1047, 1319].forEach((f, i) => tone(f, i * .085, .3, 'triangle', .055)); },
336:     advance() { [392, 523, 659].forEach((f, i) => tone(f, i * .07, .22, 'sine', .04)); },
337:     error() { tone(200, 0, .14, 'sawtooth', .025, 160); },
338:   };
