386: function toast(message, { icon = '✨', tone = '', duration = 3600 } = {}) {
387:   const root = $('#toasts'); if (!root) return;
388:   while (root.children.length >= 4) root.firstElementChild.remove();
389:   const el = document.createElement('div');
390:   el.className = `toast ${tone}`;
391:   el.innerHTML = `<span class="toast-icon">${icon}</span><span>${message}</span>`;
392:   root.appendChild(el);
393:   setTimeout(() => { el.classList.add('out'); setTimeout(() => el.remove(), 320); }, duration);
394: }
