745: function ledgerView() {
746:   const propertyEntries = state.ledger.filter((e) => ui.ledgerBuildingId === 'all' || e.buildingId === ui.ledgerBuildingId);
747:   const months = [...new Set(propertyEntries.map((e) => e.monthKey).filter(Boolean))].sort().reverse();
748:   if (ui.ledgerMonthKey !== 'all' && !months.includes(ui.ledgerMonthKey)) ui.ledgerMonthKey = 'all';
749:   const filtered = propertyEntries.filter((e) => ui.ledgerMonthKey === 'all' || e.monthKey === ui.ledgerMonthKey)
750:     .slice().sort((a, b) => b.ts - a.ts);
751:   const rows = filtered.map((e) => {
752:     const kind = e.type === 'payment' || e.type === 'partial' ? 'Payment' : e.type === 'charge' ? 'Rent charge' : e.type === 'rollover' ? 'Month rollover' : 'Adjustment';
753:     const cls = e.type === 'payment' ? 'paid' : e.type === 'partial' ? 'partial' : e.type === 'adjustment' ? 'adjustment' : 'charge';
754:     const amount = e.type === 'payment' || e.type === 'partial' ? `− ${money(e.amount)}` : e.type === 'charge' ? money(e.rent) : e.type === 'adjustment' && e.amount ? money(e.amount) : '—';
755:     const balance = e.dueAfter < -.004 ? `${money(-e.dueAfter)} credit` : money(Math.max(0, e.dueAfter));
756:     return `<tr><td data-label="Month / date"><b>${esc(e.monthLabel || e.monthKey || '')}</b><small>${formatDate(e.ts)} · ${formatTime(e.ts)}</small></td>
757:       <td data-label="Tenant"><span class="ledger-tenant">${esc(e.tenantName || 'Former tenant')}<small>${esc(e.unit ? `Apt ${e.unit}` : '')}</small></span></td>
758:       <td data-label="Building">${esc(e.buildingName || getBuilding(e.buildingId)?.name || 'Removed building')}</td>
759:       <td data-label="Activity"><span class="ledger-kind ${cls}">${kind}</span><small>${esc(e.note || '')}</small></td>
760:       <td data-label="Amount" class="money-cell ${e.type === 'payment' || e.type === 'partial' ? 'positive' : ''}">${amount}</td>
761:       <td data-label="Balance after" class="money-cell"><b>${balance}</b></td></tr>`;
762:   }).join('');
763:   const monthOptions = months.map((key) => {
